do $$declare terms jsonb;address jsonb;o public.orders;c marketplace_private.delivery_checkouts;
buyer uuid;seller uuid;outsider uuid;reply jsonb;attempt uuid;original timestamptz;begin
select p.buyer,p.seller,p.outsider into buyer,seller,outsider from bc_people p;
terms:='{"item_amount_cents":10000,"fulfillment":"delivery","delivery_method":"seller_delivery","delivery_fee_cents":1000,"delivery_area":{"country_code":"CA","province_code":"ON","city_label":"London","postal_prefix":"N6A"}}';
address:='{"country_code":"CA","province_code":"ON","city":"Postal municipality differs","postal_code":"n6a 1a1","street":"123 Synthetic Test St","unit":"4"}';
o:=pg_temp.bc_accept(terms,true);
select * into c from marketplace_private.delivery_checkouts where order_id=o.id;
perform pg_temp.bc_assert(c.checkout_started_at=o.accepted_at and c.payment_deadline_at=o.accepted_at+interval '30 minutes' and c.checkout_claim_deadline_at is null,'Seller origin immediate immutable 30 minutes');
original:=c.payment_deadline_at;
perform public.marketplace_start_delivery_checkout(o.id);perform public.marketplace_start_delivery_checkout(o.id);
perform pg_temp.bc_assert((public.marketplace_delivery_checkout(o.id)->>'paymentDeadlineAt')::timestamptz=original,'checkout retry cannot reset');
perform pg_temp.bc_reject(format('select public.marketplace_save_delivery_address(%L,%L::jsonb)',o.id,address||'{"postal_code":"M5V1A1"}'),'23514');
reply:=public.marketplace_save_delivery_address(o.id,address);
perform pg_temp.bc_assert(reply->'address'->>'postal_code'='N6A1A1','matching prefix accepts different human city');
perform pg_temp.bc_actor(seller);reply:=public.marketplace_delivery_checkout(o.id);
perform pg_temp.bc_assert(reply->'address'='null'::jsonb,'Seller cannot see unpaid address');
perform pg_temp.bc_reject(format('select public.marketplace_save_delivery_address(%L,%L::jsonb)',o.id,address),'42501');
perform pg_temp.bc_actor(outsider);perform pg_temp.bc_reject(format('select public.marketplace_delivery_checkout(%L)',o.id),'42501');
perform pg_temp.bc_actor(buyer);
perform public.marketplace_record_financial_capability(buyer,'payment_method','set','staging_test','bc_fixture','bc_method','Test Card','1234');
reply:=public.marketplace_start_order_payment(o.id,gen_random_uuid());attempt:=(reply->>'attemptId')::uuid;
perform pg_temp.bc_assert(reply->>'status'='processing','shared Delivery payment starts');
perform pg_temp.bc_assert(public.marketplace_start_order_payment(o.id,gen_random_uuid())->>'attemptId'=attempt::text,'lost client command reconciles same attempt');
perform pg_temp.bc_reject(format('select public.marketplace_save_delivery_address(%L,%L::jsonb)',o.id,address),'23505');
-- Synthetic clock setup affects only this rollback-only Order's private checkout row.
update marketplace_private.delivery_checkouts set checkout_started_at=clock.t-interval '31 minutes',payment_deadline_at=clock.t-interval '1 minute' from(select clock_timestamp() t) clock where order_id=o.id;
perform marketplace_private.settle_delivery_checkout(o.listing_id);
perform pg_temp.bc_assert(exists(select 1 from public.orders where id=o.id and lifecycle_status='open' and payment_status='processing' and holds_listing),'Processing protects inventory after deadline');
perform set_config('request.jwt.claims','{"role":"service_role","ref":"pcaqxezdfxofysghssyo"}',true);
perform public.marketplace_resolve_campus_payment(attempt,true);perform public.marketplace_resolve_campus_payment(attempt,true);
perform pg_temp.bc_actor(seller);reply:=public.marketplace_delivery_checkout(o.id);
perform pg_temp.bc_assert(reply->'address'->>'street'='123 Synthetic Test St','Seller exact address only after Paid');
perform pg_temp.bc_assert((select count(*)=1 from public.transaction_events where order_id=o.id and event_type='payment_paid'),'Paid event exactly once');
perform pg_temp.bc_assert(exists(select 1 from public.listings where id=o.listing_id and status='pending' and reserved_order_id=o.id),'Paid never releases inventory');
perform pg_temp.bc_assert(not exists(select 1 from public.transaction_events where order_id=o.id and metadata::text like '%Synthetic Test St%') and not exists(select 1 from public.notifications where destination::text like '%Synthetic Test St%'),'no address event/notification leak');
o:=pg_temp.bc_accept(terms,false);perform pg_temp.bc_actor(buyer);
select * into c from marketplace_private.delivery_checkouts where order_id=o.id;
perform pg_temp.bc_assert(c.checkout_started_at is null and c.checkout_claim_deadline_at=o.accepted_at+interval '12 hours','Buyer origin 12 hour claim');
perform public.marketplace_start_delivery_checkout(o.id);original:=(public.marketplace_delivery_checkout(o.id)->>'paymentDeadlineAt')::timestamptz;
perform public.marketplace_start_delivery_checkout(o.id);
perform pg_temp.bc_assert((public.marketplace_delivery_checkout(o.id)->>'paymentDeadlineAt')::timestamptz=original,'Buyer claim once');
update marketplace_private.delivery_checkouts set checkout_started_at=clock.t-interval '31 minutes',payment_deadline_at=clock.t-interval '1 minute' from(select clock_timestamp() t) clock where order_id=o.id;
perform marketplace_private.settle_delivery_checkout(o.listing_id);perform marketplace_private.settle_delivery_checkout(o.listing_id);
perform pg_temp.bc_assert(exists(select 1 from public.orders where id=o.id and lifecycle_status='expired' and not holds_listing),'unpaid payment deadline expires');
perform pg_temp.bc_assert(exists(select 1 from public.order_requests where id=o.request_id and status='accepted'),'accepted history never rewritten');
perform pg_temp.bc_assert(exists(select 1 from public.listings where id=o.listing_id and status='available' and reserved_order_id is null),'expiry releases Listing');
perform pg_temp.bc_assert((select count(*)=1 from public.transaction_events where order_id=o.id and event_type='reservation_expired'),'expiry event once');
perform pg_temp.bc_reject(format('select public.marketplace_start_delivery_checkout(%L)',o.id),'23505');
o:=pg_temp.bc_accept(terms,false);perform pg_temp.bc_actor(buyer);
update marketplace_private.delivery_checkouts set checkout_claim_deadline_at=clock_timestamp()-interval '1 second' where order_id=o.id;
perform marketplace_private.settle_delivery_checkout(o.listing_id);
perform pg_temp.bc_reject(format('select public.marketplace_start_delivery_checkout(%L)',o.id),'23505');
perform pg_temp.bc_assert(not has_table_privilege('authenticated','marketplace_private.delivery_checkouts','SELECT'),'address private RLS/no grants');
end;$$;
